Solution A: ```javascript
function createSpaceInvadersGame(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    canvas.width = 500;
    canvas.height = 500;

    let player = { x: 250, y: 450, width: 20, height: 20, speed: 5 };
    let enemies = [];
    let bullets = [];
    let score = 0;
    let level = 1;
    let gameRunning = true;
    let enemySpeed = 1;
    let enemyShootInterval = 2000;

    function initEnemies() {
        for (let i = 0; i < 5; i++) {
            for (let j = 0; j < 10; j++) {
                enemies.push({ x: j * 40 + 20, y: i * 30 + 20, width: 20, height: 20, health: 3 });
            }
        }
    }

    function drawPlayer() {
        ctx.fillStyle = 'blue';
        ctx.fillRect(player.x, player.y, player.width, player.height);
    }

    function drawEnemies() {
        enemies.forEach(enemy => {
            if (enemy.health > 0) {
                ctx.fillStyle = 'red';
                ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height);
            }
        });
    }

    function drawBullets() {
        bullets.forEach(bullet => {
            ctx.fillStyle = 'white';
            ctx.fillRect(bullet.x, bullet.y, bullet.width, bullet.height);
        });
    }

    function updatePlayerPosition() {
        if (keys['ArrowLeft'] && player.x > 0) {
            player.x -= player.speed;
        }
        if (keys['ArrowRight'] && player.x < canvas.width - player.width) {
            player.x += player.speed;
        }
    }

    function shootBullet() {
        if (!gameRunning) return;
        bullets.push({ x: player.x + player.width / 2, y: player.y, width: 5, height: 10, speed: -7 });
    }

    function updateBullets() {
        bullets.forEach((bullet, index) => {
            bullet.y += bullet.speed;
            if (bullet.y < 0) {
                bullets.splice(index, 1);
            }
        });
    }

    function checkCollisions() {
        bullets.forEach((bullet, bIndex) => {
            enemies.forEach((enemy, eIndex) => {
                if (bullet.x < enemy.x + enemy.width &&
                    bullet.x + bullet.width > enemy.x &&
                    bullet.y < enemy.y + enemy.height &&
                    bullet.y + bullet.height > enemy.y) {
                    enemy.health--;
                    bullets.splice(bIndex, 1);
                    if (enemy.health <= 0) {
                        enemies.splice(eIndex, 1);
                        score++;
                    }
                }
            });

            if (player.x < enemy.x + enemy.width &&
                player.x + player.width > enemy.x &&
                player.y < enemy.y + enemy.height &&
                player.y + player.height > enemy.y) {
                gameRunning = false;
            }
        });
    }

    function moveEnemies() {
        enemies.forEach(enemy => {
            enemy.x += enemySpeed;
        });

        if (enemies.some(enemy => enemy.x >= canvas.width - enemy.width || enemy.x <= 0)) {
            enemies.forEach(enemy => enemy.y += 10);
            enemySpeed *= -1;
        }
    }

    function enemyShoots() {
        if (Math.random() < 0.01 && enemies.length > 0) {
            const randomEnemy = Math.floor(Math.random() * enemies.length);
            bullets.push({ x: enemies[randomEnemy].x + enemies[randomEnemy].width / 2, y: enemies[randomEnemy].y + enemies[randomEnemy].height, width: 5, height: 10, speed: 7 });
        }
    }

    function updateScore() {
        ctx.font = '20px Arial';
        ctx.fillStyle = 'black';
        ctx.fillText(`Score: ${score}`, 10, 30);
    }

    function checkWinLose() {
        if (enemies.length === 0) {
            level++;
            initEnemies();
            enemySpeed += 1;
            enemyShootInterval -= 500;
        }
        if (enemies.some(enemy => enemy.y >= canvas.height - enemy.height) || !gameRunning) {
            gameRunning = false;
            ctx.font = '30px Arial';
            ctx.fillStyle = 'black';
            ctx.fillText('Game Over', 150, 250);
        }
    }

    function gameLoop() {
        if (!gameRunning) return;

        ctx.clearRect(0, 0, canvas.width, canvas.height);

        drawPlayer();
        drawEnemies();
        drawBullets();

        updatePlayerPosition();
        updateBullets();
        checkCollisions();
        moveEnemies();
        enemyShoots();
        updateScore();
        checkWinLose();

        requestAnimationFrame(gameLoop);
    }

    let keys = {};
    window.addEventListener('keydown', event => {
        keys[event.key] = true;
        if (event.key === ' ') {
            shootBullet();
        }
    });

    window.addEventListener('keyup', event => {
        keys[event.key] = false;
    });

    initEnemies();
    gameLoop();
}
```

Solution B: function initSpaceInvaders(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    canvas.width = 500;
    canvas.height = 500;

    const keys = {};
    document.addEventListener('keydown', e => { keys[e.code] = true; });
    document.addEventListener('keyup', e => { keys[e.code] = false; });

    const player = {
        x: canvas.width / 2,
        y: canvas.height - 30,
        w: 30,
        h: 20,
        speed: 5,
        cooldown: 0,
        alive: true
    };

    const bullets = [];
    const enemyBullets = [];
    const enemies = [];
    const explosions = [];

    let score = 0;
    let level = 1;
    let enemyDirection = 1;
    let enemySpeed = 0.5;
    let enemyTimer = 0;
    let gameOver = false;
    let win = false;

    function createEnemies() {
        enemies.length = 0;
        const rows = 4;
        const cols = 8;
        const spacingX = 50;
        const spacingY = 40;
        const offsetX = (canvas.width - (cols - 1) * spacingX) / 2;
        const offsetY = 60;
        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                enemies.push({
                    x: offsetX + c * spacingX,
                    y: offsetY + r * spacingY,
                    w: 30,
                    h: 20,
                    type: 'alien',
                    alive: true
                });
            }
        }
    }

    createEnemies();

    function loop() {
        if (gameOver) {
            drawGameOver();
            return;
        }
        update();
        draw();
        requestAnimationFrame(loop);
    }

    function update() {
        // Player movement
        if (keys['ArrowLeft']) player.x -= player.speed;
        if (keys['ArrowRight']) player.x += player.speed;
        if (player.x < 0) player.x = 0;
        if (player.x + player.w > canvas.width) player.x = canvas.width - player.w;

        // Player shooting
        if (keys['Space'] && player.cooldown <= 0 && player.alive) {
            bullets.push({
                x: player.x + player.w / 2 - 2,
                y: player.y,
                w: 4,
                h: 10,
                speed: 7
            });
            player.cooldown = 15;
        }
        if (player.cooldown > 0) player.cooldown--;

        // Update bullets
        for (let i = bullets.length - 1; i >= 0; i--) {
            bullets[i].y -= bullets[i].speed;
            if (bullets[i].y + bullets[i].h < 0) bullets.splice(i, 1);
        }

        // Enemy movement
        let moveDown = false;
        for (let e of enemies) {
            if (!e.alive) continue;
            e.x += enemyDirection * enemySpeed;
            if (e.x < 0 || e.x + e.w > canvas.width) moveDown = true;
        }
        if (moveDown) {
            enemyDirection *= -1;
            for (let e of enemies) {
                if (!e.alive) continue;
                e.y += 10;
            }
        }

        // Enemy shooting
        enemyTimer--;
        if (enemyTimer <= 0) {
            const shooters = enemies.filter(e => e.alive);
            if (shooters.length) {
                const shooter = shooters[Math.floor(Math.random() * shooters.length)];
                enemyBullets.push({
                    x: shooter.x + shooter.w / 2 - 2,
                    y: shooter.y + shooter.h,
                    w: 4,
                    h: 10,
                    speed: 4
                });
            }
            enemyTimer = Math.max(30 - level * 2, 10);
        }

        // Update enemy bullets
        for (let i = enemyBullets.length - 1; i >= 0; i--) {
            const b = enemyBullets[i];
            b.y += b.speed;
            if (b.y > canvas.height) enemyBullets.splice(i, 1);
        }

        // Collisions player bullets vs enemies
        for (let i = bullets.length - 1; i >= 0; i--) {
            const b = bullets[i];
            for (let j = enemies.length - 1; j >= 0; j--) {
                const e = enemies[j];
                if (!e.alive) continue;
                if (b.x < e.x + e.w && b.x + b.w > e.x && b.y < e.y + e.h && b.y + b.h > e.y) {
                    e.alive = false;
                    bullets.splice(i, 1);
                    score += 10;
                    explosions.push({
                        x: e.x + e.w / 2,
                        y: e.y + e.h / 2,
                        r: 0,
                        maxR: 15,
                        life: 15
                    });
                    break;
                }
            }
        }

        // Collisions enemy bullets vs player
        if (player.alive) {
            for (let i = enemyBullets.length - 1; i >= 0; i--) {
                const b = enemyBullets[i];
                if (b.x < player.x + player.w && b.x + b.w > player.x && b.y < player.y + player.h && b.y + b.h > player.y) {
                    player.alive = false;
                    enemyBullets.splice(i, 1);
                    explosions.push({
                        x: player.x + player.w / 2,
                        y: player.y + player.h / 2,
                        r: 0,
                        maxR: 20,
                        life: 20
                    });
                    break;
                }
            }
        }

        // Enemy reaches bottom
        for (let e of enemies) {
            if (e.alive && e.y + e.h >= canvas.height) {
                gameOver = true;
                break;
            }
        }

        // Win condition
        if (enemies.every(e => !e.alive)) {
            level++;
            enemySpeed += 0.2;
            createEnemies();
        }

        // Update explosions
        for (let i = explosions.length - 1; i >= 0; i--) {
            const ex = explosions[i];
            ex.r += ex.maxR / ex.life;
            ex.life--;
            if (ex.life <= 0) explosions.splice(i, 1);
        }
    }

    function draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        // Draw player
        if (player.alive) {
            ctx.fillStyle = '#0f0';
            ctx.beginPath();
            ctx.moveTo(player.x, player.y + player.h);
            ctx.lineTo(player.x + player.w / 2, player.y);
            ctx.lineTo(player.x + player.w, player.y + player.h);
            ctx.closePath();
            ctx.fill();
        }

        // Draw bullets
        ctx.fillStyle = '#fff';
        for (let b of bullets) {
            ctx.fillRect(b.x, b.y, b.w, b.h);
        }
        ctx.fillStyle = '#f00';
        for (let b of enemyBullets) {
            ctx.fillRect(b.x, b.y, b.w, b.h);
        }

        // Draw enemies
        ctx.fillStyle = '#00f';
        for (let e of enemies) {
            if (!e.alive) continue;
            ctx.fillRect(e.x, e.y, e.w, e.h);
        }

        // Draw explosions
        ctx.fillStyle = 'orange';
        for (let ex of explosions) {
            ctx.beginPath();
            ctx.arc(ex.x, ex.y, ex.r, 0, Math.PI * 2);
            ctx.fill();
        }

        // Draw UI
        ctx.fillStyle = '#fff';
        ctx.font = '16px sans-serif';
        ctx.fillText('Score: ' + score, 10, 20);
        ctx.fillText('Level: ' + level, canvas.width - 80, 20);
    }

    function drawGameOver() {
        ctx.fillStyle = 'rgba(0,0,0,0.7)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = '#fff';
        ctx.font = '30px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(win ? 'You Win!' : 'Game Over', canvas.width / 2, canvas.height / 2 - 20);
        ctx.font = '20px sans-serif';
        ctx.fillText('Score: ' + score, canvas.width / 2, canvas.height / 2 + 10);
    }

    requestAnimationFrame(loop);
}

